CREATE FUNCTION b197_f17b() RETURNS void LANGUAGE sql BEGIN ATOMIC EXPLAIN SELECT 1; END;
-- regression: expanding a plpgsql record Param goes through
-- get_expr_result_tupdesc with noError=false (parse_target.c:1470).
DO $$ DECLARE r record; x int; BEGIN SELECT 1 AS a, 2 AS b INTO r; SELECT count(*) INTO x FROM (SELECT r.*) s; RAISE NOTICE 'x=%', x; END $$;
DO $$ DECLARE r record; x int; BEGIN SELECT 1 AS a, 2 AS b INTO r; SELECT (r).* INTO x; RAISE NOTICE 'x=%', x; END $$;
DO $$ DECLARE r record; x int; BEGIN SELECT count(*) INTO x FROM (SELECT r.*) s; RAISE NOTICE 'x=%', x; END $$;
CREATE TYPE b197_rt AS (a int, b int);
DO $$ DECLARE r b197_rt; x int; BEGIN SELECT 1, 2 INTO r; SELECT count(*) INTO x FROM (SELECT r.*) s; RAISE NOTICE 'x=%', x; END $$;
DO $$ DECLARE r b197_rt; x int; BEGIN SELECT 1, 2 INTO r; SELECT a + b INTO x FROM (SELECT r.*) s; RAISE NOTICE 'x=%', x; END $$;
DROP TYPE b197_rt;
-- regression: r.* skips an inner scalar r (pl_funcs.c:146) and
-- finds the outer record.
DO $$ DECLARE r record; x int; BEGIN SELECT 1 AS a, 2 AS b INTO r;
  DECLARE r int := 5; BEGIN
    RAISE NOTICE 'r=%', r;
    RAISE NOTICE 'ra=%', r.a;
    SELECT count(*) INTO x FROM (SELECT r.*) s; RAISE NOTICE 'x=%', x;
  END;
END $$;
CREATE TYPE b197_rt AS (a int, b int);
DO $$ DECLARE r b197_rt; x int; BEGIN SELECT 1, 2 INTO r;
  DECLARE r int := 5; BEGIN
    RAISE NOTICE 'r=%', r;
    SELECT a + b INTO x FROM (SELECT r.*) s; RAISE NOTICE 'x=%', x;
  END;
END $$;
DO $$ DECLARE r int := 5; x int; BEGIN
  SELECT r INTO x FROM (SELECT r.*) s; RAISE NOTICE 'x=%', x;
END $$;
-- regression: a field literally named "*" does not capture r.*
-- (pl_comp.c:1133 distinguishes A_Star from a quoted name).
DO $$ DECLARE r record; x int; BEGIN SELECT 1 AS "*", 2 AS b INTO r; x := r."*"; RAISE NOTICE 'x=%', x; SELECT count(*) INTO x FROM (SELECT r.*) s; RAISE NOTICE 'x=%', x; END $$;
DO $$ DECLARE r b197_rt; x int; BEGIN SELECT 1, 2 INTO r; x := r."*"; RAISE NOTICE 'x=%', x; END $$;
DROP TYPE b197_rt;
